import{_ as t,o,c as a,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Plain-Text-Output-Options.md","filePath":"manual-en/Plain-Text-Output-Options.md","lastUpdated":1785684581000}'),i={name:"manual-en/Plain-Text-Output-Options.md"};function s(r,e,p,d,c,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h3 id="_3-3-plain-text-output-options" tabindex="-1">3.3 Plain Text Output Options <a class="header-anchor" href="#_3-3-plain-text-output-options" aria-label="Permalink to &quot;3.3 Plain Text Output Options&quot;">​</a></h3><p>PSPP can produce plain text output, drawing boxes using ASCII or Unicode line drawing characters. To produce plain text output, specify -o file on the PSPP command line, optionally followed by options from the table below to customize the output format.</p><p>Plain text output is encoded in UTF-8.</p><p>-O format=txt</p><p>Specify the output format. This is only necessary if the file name given on -o does not end in .txt or .list.</p><p>-O charts={template.png|none}</p><p>Name for chart files included in output. The value should be a file name that includes a single ‘#’ and ends in png. When a chart is output, the ‘#’ is replaced by the chart number. The default is the file name specified on -o with the extension stripped off and replaced by -#.png.</p><p>Specify <code>none</code> to disable chart output.</p><p>-O foreground-color=color -O background-color=color</p><p>Sets color as the color to be used for the background or foreground to be used for charts. Color should be given in the format <code>#RRRRGGGGBBBB</code>, where RRRR, GGGG and BBBB are 4 character hexadecimal representations of the red, green and blue components respectively. If charts are disabled, this option has no effect.</p><p>-O width=columns</p><p>Width of a page, in columns. If unspecified or given as <code>auto</code>, the default is the width of the terminal, for interactive output, or the WIDTH setting (see <a href="./SET">SET</a>), for output to a file.</p><p>-O box={ascii|unicode}</p><p>Sets the characters used for lines in tables. If set to <code>ascii</code>, output uses use the characters ‘-’, ‘|’, and ‘+’ for single-width lines and ‘=’ and ‘#’ for double-width lines. If set to <code>unicode</code> then, output uses Unicode box drawing characters. The default is <code>unicode</code> if the locale’s character encoding is &quot;UTF-8&quot; or <code>ascii</code> otherwise.</p><p>-O emphasis={none|bold|underline}</p><p>How to emphasize text. Bold and underline emphasis are achieved with overstriking, which may not be supported by all the software to which you might pass the output. Default: <code>none</code>.</p>',16)])])}const f=t(i,[["render",s]]);export{h as __pageData,f as default};
